input.content:
:root {
  --ink: #070918;
  --ink-2: #0d1228;
  --paper: #f4f5ff;
  --muted: #9ca5c6;
  --lime: #c9ff3b;
  --cyan: #21e9ff;
  --pink: #ff3ec8;
  --orange: #ff8a2b;
  --violet: #7c5cff;
  --danger: #ff4d62;
  --accent: var(--cyan);
  --font-display: "Barlow Condensed", "Arial Narrow", Impact, sans-serif;
  --font-body: "Space Grotesk", "Trebuchet MS", sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--font-body);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { touch-action: none; }

button {
  font-family: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible { outline: 2px solid var(--lime); outline-offset: 3px; }

#app {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #050817;
  user-select: none;
  -webkit-user-select: none;
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.screen-fx {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: 0.36;
  background-image:
    repeating-linear-gradient(0deg, rgba(255,255,255,.025) 0 1px, transparent 1px 3px),
    radial-gradient(circle at 50% 50%, transparent 55%, rgba(0,0,0,.38) 100%);
  mix-blend-mode: soft-light;
}

.vignette {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 45%, transparent 45%, rgba(2,3,12,.55) 100%);
}

.hidden { display: none !important; }

.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  opacity: 1;
  transition: opacity .35s ease, visibility .35s;
}
.screen.fade-out { opacity: 0; visibility: hidden; pointer-events: none; }

/* ============================== LOADING ============================== */
.loading {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: #050817;
  transition: opacity .6s ease, visibility .6s;
}
.loading.done { opacity: 0; visibility: hidden; pointer-events: none; }
.loading-mark {
  width: 72px; height: 72px;
  display: grid; place-items: center;
  border-radius: 18px;
  background: var(--lime);
  color: #071018;
  font-family: var(--font-display);
  font-size: 38px; font-weight: 900; font-style: italic;
  transform: skew(-7deg);
  animation: loadPulse 1.2s ease-in-out infinite;
}
.loading-text {
  font-size: 10px; letter-spacing: .34em; font-weight: 700; color: var(--muted);
}
@keyframes loadPulse { 50% { transform: skew(-7deg) scale(1.08); box-shadow: 0 0 50px rgba(201,255,59,.35); } }

/* ============================== MENU ============================== */
.menu-screen {
  overflow: hidden;
  background:
    radial-gradient(ellipse at 72% 38%, rgba(26, 208, 255, .09), transparent 45%),
    linear-gradient(100deg, rgba(4,6,18,.97) 0%, rgba(4,6,18,.88) 34%, rgba(4,6,18,.45) 66%, rgba(4,6,18,.62) 100%);
}
.menu-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(255,255,255,.1) .6px, transparent .6px);
  background-size: 5px 5px;
  opacity: .2;
  mix-blend-mode: overlay;
}
.menu-screen::after {
  content: "";
  position: absolute;
  left: 0; bottom: 0;
  width: 48%; height: 42%;
  pointer-events: none;
  background: radial-gradient(ellipse at 0% 100%, rgba(255,62,200,.13), transparent 65%);
}

.menu-top {
  position: relative;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: max(24px, env(safe-area-inset-top)) clamp(22px, 3.4vw, 54px) 0;
}
.brand { display: flex; align-items: center; gap: 13px; }
.brand-mark {
  width: 45px; height: 45px;
  display: grid; place-items: center;
  background: var(--lime);
  color: #06101a;
  font-family: var(--font-display);
  font-size: 25px; font-weight: 900; font-style: italic;
  letter-spacing: -.04em;
  transform: skew(-8deg);
  box-shadow: 0 0 34px rgba(201,255,59,.22);
}
.brand-copy {
  display: flex;
  flex-direction: column;
  font-family: var(--font-display);
  font-size: 18px; line-height: 1; font-weight: 800; font-style: italic;
  letter-spacing: .07em;
}
.brand-copy small {
  margin-top: 4px;
  font-family: var(--font-body);
  font-size: 7px; font-weight: 600; letter-spacing: .32em; color: var(--muted);
}
.menu-meta {
  display: flex; align-items: center; gap: 12px;
  font-size: 9px; letter-spacing: .25em; font-weight: 700; color: #c7cce4;
}
.live-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--danger); box-shadow: 0 0 0 4px rgba(255,77,98,.12);
  animation: blink 1.5s infinite;
}
@keyframes blink { 50% { opacity: .3; } }

.menu-grid {
  position: relative;
  z-index: 4;
  height: calc(100% - 150px);
  display: grid;
  grid-template-columns: minmax(300px, .88fr) minmax(440px, 1.12fr);
  align-items: center;
  gap: clamp(28px, 5vw, 90px);
  padding: 0 clamp(22px, 5.2vw, 82px);
  max-width: 1540px;
  margin: 0 auto;
}
.hero { position: relative; padding-bottom: 6vh; }
.hero-eyebrow {
  display: flex; align-items: center; gap: 12px;
  font-size: 9px; font-weight: 700; letter-spacing: .32em; color: var(--lime);
  margin-bottom: clamp(14px, 2vh, 28px);
  animation: slideUp .7s .1s both;
}
.hero-eyebrow span { width: 26px; height: 1px; background: currentColor; opacity: .55; }
.hero h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(72px, 9.6vw, 150px);
  font-weight: 900;
  font-style: italic;
  line-height: .72;
  letter-spacing: -.045em;
  text-transform: uppercase;
  text-shadow: 0 18px 60px rgba(0,0,0,.5);
  animation: slideUp .7s .16s both;
}
.hero h1 em {
  font-style: italic;
  background: linear-gradient(100deg, var(--lime), #f4ffd2 35%, var(--cyan) 100%);
  -webkit-background-clip: text; background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 26px rgba(201,255,59,.17));
}
.hero-tag {
  margin: clamp(16px, 2.4vh, 30px) 0 0;
  font-size: clamp(12px, 1.02vw, 15px);
  line-height: 1.7;
  color: #bfc5df;
  max-width: 380px;
  animation: slideUp .7s .24s both;
}
.hero-stats {
  display: flex;
  gap: clamp(24px, 3vw, 50px);
  margin-top: clamp(22px, 4vh, 48px);
  animation: slideUp .7s .32s both;
}
.hero-stats div { display: flex; flex-direction: column; gap: 3px; }
.hero-stats b {
  font-family: var(--font-display);
  font-size: clamp(22px, 2vw, 30px); font-style: italic; line-height: 1;
}
.hero-stats span { font-size: 7px; letter-spacing: .22em; color: var(--muted); font-weight: 600; }
@keyframes slideUp { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }

.setup { animation: slideUp .7s .34s both; max-width: 640px; justify-self: end; width: 100%; }
.setup-head { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 15px; }
.setup-num {
  font-family: var(--font-display);
  color: var(--lime); font-size: 11px; font-style: italic; font-weight: 800;
  padding-top: 4px;
}
.setup-head h2, .block-label { margin: 0; font-family: var(--font-display); font-size: 16px; font-weight: 800; letter-spacing: .07em; }
.setup-head p { margin: 3px 0 0; font-size: 9px; color: var(--muted); letter-spacing: .04em; }
.playstyles { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.ps-card {
  position: relative;
  display: grid;
  grid-template-columns: 37px 1fr;
  grid-template-rows: auto auto;
  gap: 2px 9px;
  text-align: left;
  padding: 12px 12px 11px;
  border: 1px solid rgba(255,255,255,.1);
  background: linear-gradient(120deg, rgba(19,25,51,.72), rgba(11,15,34,.48));
  backdrop-filter: blur(8px);
  overflow: hidden;
  transition: border-color .2s, background .2s, transform .2s;
}
.ps-card::after {
  content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 2px;
  background: var(--psc, var(--cyan)); opacity: .4; transition: opacity .2s;
}
.ps-card:hover { transform: translateY(-2px); border-color: rgba(255,255,255,.24); }
.ps-card.selected {
  border-color: var(--psc, var(--cyan));
  background: linear-gradient(120deg, rgba(33,233,255,.15), rgba(11,15,34,.68));
  box-shadow: inset 0 0 30px rgba(33,233,255,.04), 0 0 0 1px rgba(255,255,255,.04);
}
.ps-card.selected::after { opacity: 1; }
.ps-card.street { --psc: var(--pink); }
.ps-card.tiki { --psc: var(--cyan); }
.ps-card.power { --psc: var(--orange); }
.ps-card.press { --psc: var(--lime); }
.ps-badge {
  grid-row: 1 / 3;
  align-self: center;
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border: 1px solid var(--psc);
  color: var(--psc);
  font-family: var(--font-display); font-size: 18px; font-weight: 900; font-style: italic;
  transform: skew(-7deg);
  background: rgba(255,255,255,.03);
}
.ps-card-copy { display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; }
.ps-card-copy b { font-family: var(--font-display); font-size: 15px; font-weight: 800; font-style: italic; letter-spacing: .04em; }
.ps-card-copy small { font-size: 7px; color: var(--muted); letter-spacing: .02em; }
.ps-perk { grid-column: 2; font-size: 8px; line-height: 1.35; color: #a9b2cf; }

.setup-row { display: flex; gap: 22px; align-items: flex-end; margin: 16px 0 15px; }
.setup-block { display: flex; flex-direction: column; gap: 8px; position: relative; }
.setup-block .setup-num { position: absolute; left: 0; bottom: 5px; padding: 0; }
.block-label { margin-left: 19px; font-size: 10px; letter-spacing: .17em; color: var(--muted); }
.segmented { display: flex; background: rgba(9,13,30,.72); border: 1px solid rgba(255,255,255,.1); padding: 3px; }
.segmented button {
  padding: 7px 12px; font-size: 8px; font-weight: 700; letter-spacing: .13em;
  color: #7f89aa; transition: .16s;
}
.segmented button.active { background: var(--paper); color: #08101e; box-shadow: 0 2px 10px rgba(0,0,0,.3); }
.kit-block { margin-left: auto; }
.kits { display: flex; gap: 7px; margin-left: 19px; }
.kit {
  width: 25px; height: 25px; border-radius: 50%;
  background: var(--kit);
  border: 2px solid transparent;
  box-shadow: inset 0 0 0 3px #0b1022, 0 0 12px color-mix(in srgb, var(--kit) 35%, transparent);
  transition: transform .16s, border-color .16s;
}
.kit.active { border-color: #fff; transform: scale(1.12); }

.start-btn {
  position: relative;
  width: 100%;
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  padding: 13px 19px;
  color: #071018;
  background: var(--lime);
  overflow: hidden;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 16px) 100%, 0 100%);
  transition: transform .18s, box-shadow .18s, filter .18s;
  box-shadow: 0 12px 38px rgba(201,255,59,.16);
}
.start-btn:hover { transform: translateY(-2px); filter: brightness(1.05); box-shadow: 0 16px 46px rgba(201,255,59,.28); }
.start-btn:active { transform: translateY(0) scale(.995); }
.start-kicker { font-size: 7px; font-weight: 700; letter-spacing: .2em; opacity: .62; }
.start-main { font-family: var(--font-display); font-size: clamp(25px, 2.2vw, 33px); font-weight: 900; font-style: italic; letter-spacing: .01em; display: flex; align-items: center; gap: 14px; }
.start-main i { font-style: normal; font-size: .8em; }
.start-shine {
  position: absolute; top: 0; left: -60%; width: 45%; height: 100%;
  background: linear-gradient(100deg, transparent, rgba(255,255,255,.5), transparent);
  transform: skewX(-18deg);
  animation: shine 4.2s 2s infinite;
}
@keyframes shine { 0%, 70% { left: -60%; } 90%, 100% { left: 130%; } }
.menu-controls { margin: 11px 0 0; font-size: 7.5px; line-height: 1.6; letter-spacing: .05em; color: #707a9c; }
.menu-controls b { color: #aab2cd; letter-spacing: .12em; }

.menu-bottom {
  position: absolute; left: 0; right: 0; bottom: 0;
  z-index: 4;
  display: flex; justify-content: space-between; align-items: center;
  padding: 0 clamp(22px, 5.2vw, 82px) max(20px, env(safe-area-inset-bottom));
  font-size: 7px; letter-spacing: .24em; color: #59617e;
}
.menu-bottom-right { color: #7d86a5; }

.rotate-prompt { display: none; }

/* ============================== HUD ============================== */
#hud {
  position: absolute; inset: 0; z-index: 10;
  pointer-events: none;
  opacity: 1;
  transition: opacity .3s;
}
#hud.ui-hidden { opacity: 0; }
.hud-top {
  position: absolute;
  top: max(13px, env(safe-area-inset-top));
  left: 0; right: 0;
  display: flex; align-items: flex-start; justify-content: space-between;
  padding: 0 max(16px, env(safe-area-inset-left)) 0 max(16px, env(safe-area-inset-right));
}
.hud-left, .hud-right { display: flex; align-items: center; gap: 10px; pointer-events: auto; }
.hud-left { min-width: 200px; }
.hud-right { min-width: 200px; justify-content: flex-end; }

.icon-btn {
  width: 38px; height: 38px; border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(8,12,28,.72);
  border: 1px solid rgba(255,255,255,.13);
  backdrop-filter: blur(8px);
  pointer-events: auto;
  transition: background .2s, transform .2s;
}
.icon-btn:hover { background: rgba(20,27,54,.9); transform: scale(1.04); }
.icon-btn span { display: block; width: 11px; height: 2px; background: #d9def1; margin: 2px; }
.icon-btn.sound { width: 34px; height: 34px; }
.icon-btn.sound svg { width: 17px; height: 17px; fill: #d9def1; }
.icon-btn.sound .wave { fill: none; stroke: #d9def1; stroke-width: 1.5; stroke-linecap: round; opacity: .8; }
.icon-btn.sound.muted .wave { opacity: .15; }
.icon-btn.sound.muted::after {
  content: ""; position: absolute; width: 19px; height: 1.5px; background: var(--danger);
  transform: rotate(-45deg);
}

.playstyle-chip {
  display: flex; align-items: center; gap: 9px;
  height: 38px; padding: 0 13px 0 8px;
  background: rgba(8,12,28,.72);
  border: 1px solid rgba(255,255,255,.13);
  backdrop-filter: blur(8px);
}
.ps-icon {
  width: 24px; height: 24px; display: grid; place-items: center;
  background: var(--accent); color: #071018; font-size: 12px;
  transform: skew(-6deg);
}
.ps-copy { display: flex; flex-direction: column; line-height: 1; }
.ps-copy small { font-size: 6px; color: #7e88a8; letter-spacing: .18em; margin-bottom: 2px; }
.ps-copy b { font-family: var(--font-display); font-size: 12px; font-style: italic; letter-spacing: .09em; }

.scoreboard {
  position: absolute;
  left: 50%; top: 0;
  transform: translateX(-50%);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 13px;
  min-width: 285px;
  height: 47px;
  padding: 0 24px;
  background: linear-gradient(180deg, rgba(10,14,32,.92), rgba(6,9,23,.8));
  border: 1px solid rgba(255,255,255,.14);
  box-shadow: 0 8px 30px rgba(0,0,0,.3);
  backdrop-filter: blur(12px);
  clip-path: polygon(12px 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 12px 100%, 0 50%);
  pointer-events: none;
}
.team { display: flex; align-items: center; gap: 6px; font-family: var(--font-display); font-size: 12px; font-weight: 800; font-style: italic; letter-spacing: .06em; }
.team.away { justify-content: flex-end; }
.kit-dot { width: 7px; height: 7px; border-radius: 50%; }
.team.home .kit-dot { background: var(--accent); box-shadow: 0 0 8px var(--accent); }
.team.away .kit-dot { background: var(--danger); box-shadow: 0 0 8px var(--danger); }
.score-nums { display: flex; align-items: baseline; gap: 7px; font-family: var(--font-display); font-size: 25px; font-weight: 900; font-style: italic; line-height: 1; }
.score-nums i { font-style: normal; color: #59617d; font-size: 15px; }
.score-nums span { min-width: 18px; text-align: center; }
.score-nums span:first-child { color: var(--accent); }
.clock {
  position: absolute; left: 50%; bottom: -15px; transform: translateX(-50%);
  padding: 2px 10px;
  background: var(--lime); color: #071018;
  font-family: var(--font-display); font-size: 10px; font-weight: 900; font-style: italic; letter-spacing: .08em;
  clip-path: polygon(5px 0, 100% 0, calc(100% - 5px) 100%, 0 100%);
}

.minimap-wrap {
  position: relative; width: 154px; height: 90px;
  background: rgba(6,10,25,.7);
  border: 1px solid rgba(255,255,255,.12);
  backdrop-filter: blur(8px);
  padding: 5px;
}
#minimap { width: 100%; height: 100%; display: block; }
.mini-label { position: absolute; right: 7px; bottom: 4px; font-size: 5px; letter-spacing: .2em; color: #707b9e; }

.hud-center {
  position: absolute; top: max(70px, calc(env(safe-area-inset-top) + 70px)); left: 50%;
  transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 5px;
  pointer-events: none;
}
.stamina-wrap { display: flex; align-items: center; gap: 7px; }
.stamina-label { font-size: 5px; letter-spacing: .2em; color: #7e88a8; font-weight: 700; }
.stamina-bar { width: 92px; height: 3px; background: rgba(255,255,255,.1); overflow: hidden; }
#stamina-fill { height: 100%; width: 100%; background: var(--accent); box-shadow: 0 0 8px var(--accent); transition: width .1s linear; }
.possession {
  padding: 4px 12px;
  font-family: var(--font-display); font-size: 8px; font-weight: 800; font-style: italic; letter-spacing: .14em;
  background: rgba(6,10,25,.66); border: 1px solid rgba(255,255,255,.1);
  color: #aeb7d2;
  opacity: 0; transform: translateY(-4px);
  transition: opacity .2s, transform .2s;
}
.possession.show { opacity: 1; transform: none; }

.event-stack {
  position: absolute; top: 140px; right: max(22px, env(safe-area-inset-right));
  display: flex; flex-direction: column; align-items: flex-end; gap: 6px;
}
.event {
  padding: 7px 11px;
  background: rgba(8,12,28,.82); border-right: 2px solid var(--accent);
  backdrop-filter: blur(8px);
  font-family: var(--font-display); font-size: 11px; font-weight: 800; font-style: italic; letter-spacing: .1em;
  animation: eventIn .35s both;
}
.event small { display: block; font-family: var(--font-body); font-size: 6px; font-weight: 600; color: #8d96b4; letter-spacing: .15em; margin-top: 2px; }
@keyframes eventIn { from { opacity: 0; transform: translateX(15px); } }
.event.out { animation: eventOut .3s both; }
@keyframes eventOut { to { opacity: 0; transform: translateX(20px); } }

.hud-bottom {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: flex; align-items: flex-end; justify-content: space-between;
  padding: 0 max(24px, env(safe-area-inset-right)) max(20px, env(safe-area-inset-bottom)) max(24px, env(safe-area-inset-left));
  pointer-events: none;
}
.joystick-zone {
  position: relative;
  width: 138px; height: 138px;
  border-radius: 50%;
  pointer-events: auto;
  touch-action: none;
  background: radial-gradient(circle, rgba(255,255,255,.035) 0 35%, rgba(8,12,28,.28) 63%, rgba(8,12,28,.05) 64%);
  border: 1px solid rgba(255,255,255,.13);
  box-shadow: inset 0 0 38px rgba(0,0,0,.2);
}
.joystick-zone.active { border-color: color-mix(in srgb, var(--accent) 55%, transparent); }
.joystick-ring {
  position: absolute; inset: 28px; border-radius: 50%;
  border: 1px dashed rgba(255,255,255,.12);
}
.joystick-knob {
  position: absolute; left: 50%; top: 50%;
  width: 60px; height: 60px; margin: -30px;
  border-radius: 50%;
  display: grid; place-items: center;
  background: linear-gradient(145deg, rgba(255,255,255,.94), rgba(181,190,219,.78));
  box-shadow: 0 6px 22px rgba(0,0,0,.38), inset 0 2px 3px #fff;
  transition: transform .05s linear;
}
.joystick-knob svg { width: 21px; height: 21px; fill: rgba(11,16,34,.62); }
.stick-label {
  position: absolute; left: 50%; bottom: -16px; transform: translateX(-50%);
  font-size: 6px; letter-spacing: .25em; color: #717c9d;
}

.control-hints {
  display: flex; gap: 15px;
  padding-bottom: 8px;
  font-size: 6px; letter-spacing: .12em; color: #5e6785;
}
.control-hints b { color: #9da6c2; margin-right: 3px; }

.action-cluster {
  display: grid;
  grid-template-columns: 62px 78px;
  grid-template-rows: 62px 78px;
  gap: 9px;
  pointer-events: auto;
}
.action {
  position: relative;
  border-radius: 50%;
