  }
}
function setOwner(p) {
  game.owner = p; game.ball.owner = p; game.ball.vel.set(0, 0, 0);
  if (p) game.ball.pos.set(p.pos.x + p.face.x * 0.58, 0.3, p.pos.z + p.face.z * 0.58);
}
